using namespace std;

class PathFinder {
    int N;
    vector<vector<pair<int, int>>> edges;
public:
    PathFinder(int n) : N(n), edges(n + 1) {}
    void addEdge(int u, int v, int w) { edges[u].push_back({v, w}); }
    vector<int> shortestPath(int start, int end) {
        vector<int> dist(N + 1, INT_MAX);
        dist[start] = 0;
        priority_queue<pair<int, int>> pq;
        pq.push({0, start});
        while (!pq.empty()) {
            int w = -pq.top().first;
            int u = pq.top().second;
            pq.pop();
            if (u == end) return dist;
            if (dist[u] < w) continue;
            for (auto &e : edges[u]) {
                int v = e.first, w2 = w + e.second;
                if (dist[v] > w2) {
                    dist[v] = w2;
                    pq.push({-w2, v});
                }
            }
        }
        return dist;
    }
    void run() {
        int n, e, s, u, v, w;
        scanf("%d%d", &n, &e);
        PathFinder pf(n);
        scanf("%d", &s);
        for (int i = 0; i < e; i++) {
            scanf("%d%d%d", &u, &v, &w);
            pf.addEdge(u, v, w);
        }
        vector<int> ans = pf.shortestPath(s, N);
        for (int i = 1; i <= n; i++) {
            if (ans[i] >= INT_MAX) printf("INF\n");
            else printf("%d\n", ans[i]);
        }
    }
};

class MinimumSpanningTree {
    int N;
    vector<vector<pair<int, int>>> E;
public:
    MinimumSpanningTree(int n) : N(n), E(n + 1) {}
    void insert(int u, int v, int w) { E[u].push_back({v, w}); }
    void compute(long long &totalCost) {
        vector<int> dist(N + 1, INT_MAX);
        vector<bool> inMST(N + 1, false);
        dist[1] = 0;
        totalCost = 0;
        priority_queue<pair<int, int>> pq;
        pq.push({0, 1});
        for (int i = 0; i < N; i++) {
            int u = -1, minDist = INT_MAX;
            while (!pq.empty()) {
                u = pq.top().second;
                pq.pop();
                if (!inMST[u]) break;
            }
            if (u == -1 || inMST[u]) break;
            inMST[u] = true;
            totalCost += dist[u];
            for (auto &edge : E[u]) {
                int v = edge.first, w = edge.second;
                if (!inMST[v] && dist[v] > w) {
                    dist[v] = w;
                    pq.push({-w, v});
                }
            }
        }
    }
    void run() {
        int n, e, u, v, w;
        scanf("%d%d", &n, &e);
        MinimumSpanningTree mst(n);
        for (int i = 0; i < e; i++) {
            scanf("%d%d%d", &u, &v, &w);
            mst.insert(u, v, w);
        }
        long long cost = 0;
        mst.compute(cost);
        printf("%lld", cost);
    }
};

class FloydAlgorithm {
    int N;
    vector<vector<int>> dist;
public:
    FloydAlgorithm(int n) : N(n), dist(n + 1, vector<int>(n + 1, INT_MAX)) {}
    void setEdge(int r, int c, int w) { dist[r][c] = w; }
    int getEdge(int r, int c) { return dist[r][c]; }
    void run() {
        for (int i = 1; i <= N; i++) dist[i][i] = 0;
        for (int k = 1; k <= N; k++)
            for (int i = 1; i <= N; i++)
                for (int j = 1; j <= N; j++)
                    if (dist[i][k] != INT_MAX && dist[k][j] != INT_MAX)
                        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
    }
};

